def raw_exercise():
    L = ['مشق', '', '۱۔ متن کے حوالے سے خالی جگہ پُر کریں۔']
    L += [f'({h}) {s}' for h, (s, _) in zip(['ا', 'ب', 'ج', 'د', 'ہ', 'و'], BLANKS)]
    nums = ['۲', '۳', '۴', '۵', '۶', '۷', '۸']
    L += [''] + [f'{n}۔ {q}' for n, (q, _) in zip(nums, QS[:7])]
    L += ['☆ ' + GRAMMAR[0]['explanation'] + ' جیسے: ۱۔ فدا نے انگور کھائے۔ ۲۔ ابرار نے گاڑی چلائی۔ ان جملوں میں "فدا اور ابرار" فاعل ہیں۔ "انگور اور گاڑی" مفعول ہیں۔ "کھائے اور چلائی" فعل ہیں۔']
    L += [f'۹۔ {QS[7][0]}', f'۱۰۔ {QS[8][0]}', '', ACTIVITY, '', TEACHER]
    return '\n'.join(L)


def fix_exercise(ex):
    ex['rawExercise'] = raw_exercise()
    ex['blanks'] = [dict(statement=s, answer=a) for s, a in BLANKS]
    ex['shortQuestions'] = [dict(question=q, answer=a) for q, a in QS]
    ex['vocabulary'] = [dict(word=w, meaning=m, sentence=s) for w, m, s in VOCAB]
    ex['grammar'] = GRAMMAR
    t = ex.setdefault('contextualTashreeh', {})
    t.update(passage=PASSAGE.strip('"'), answer=QS[8][1], answerLabel='SpaceBook answer (the textbook prints no answers)')
    for k in ('reference', 'context', 'explanation'):
        t.pop(k, None)
    ex['activity'] = ACTIVITY.split(': ', 1)[1]
    ex['teacherInstructions'] = [TEACHER.split(': ', 1)[1]]
    ex['answerNote'] = 'SpaceBook answers (the textbook prints no answers).'


